const listUpcomingBookingRequests = `-- name: ListUpcomingBookingRequests :many
SELECT br.id, br.booker_id, br.start, br."end", br.created, br.event, br.status,
       m.id AS booker_member_id, m.student_id AS booker_student_id,
       m.first_name AS booker_first_name, m.last_name AS booker_last_name,
       m.nickname AS booker_nickname, m.picture_path AS booker_picture_path
FROM booking_requests br
LEFT JOIN members m ON m.id = br.booker_id
WHERE br.start >= $1
ORDER BY br.start ASC NULLS LAST, br."end" ASC NULLS LAST, br.status ASC
`

type ListUpcomingBookingRequestsRow struct {
	ID                pgtype.UUID          `json:"id"`
	BookerID          pgtype.UUID          `json:"booker_id"`
	Start             pgtype.Timestamptz   `json:"start"`
	End               pgtype.Timestamptz   `json:"end"`
	Created           pgtype.Timestamptz   `json:"created"`
	Event             pgtype.Text          `json:"event"`
	Status            BookingRequestStatus `json:"status"`
	BookerMemberID    pgtype.UUID          `json:"booker_member_id"`
	BookerStudentID   pgtype.Text          `json:"booker_student_id"`
	BookerFirstName   pgtype.Text          `json:"booker_first_name"`
	BookerLastName    pgtype.Text          `json:"booker_last_name"`
	BookerNickname    pgtype.Text          `json:"booker_nickname"`
	BookerPicturePath pgtype.Text          `json:"booker_picture_path"`
}

// Mirrors the old app's getUpcomingBookingRequests: every request starting
// on or after `since` (callers pass now-1week, matching the old hardcoded
// window), regardless of booker - visibility is gated at the service layer
// (booking_request:read), not per-row ownership.
func (q *Queries) ListUpcomingBookingRequests(ctx context.Context, since pgtype.Timestamptz) ([]ListUpcomingBookingRequestsRow, error) {
	rows, err := q.db.Query(ctx, listUpcomingBookingRequests, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUpcomingBookingRequestsRow{}
	for rows.Next() {
		var i ListUpcomingBookingRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.BookerID,
			&i.Start,
			&i.End,
			&i.Created,
			&i.Event,
			&i.Status,
			&i.BookerMemberID,
			&i.BookerStudentID,
			&i.BookerFirstName,
			&i.BookerLastName,
			&i.BookerNickname,
			&i.BookerPicturePath,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

